const { useState } = React;

function App() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [message, setMessage] = useState("");
  const [errors, setErrors] = useState({});

  const validateEmail = (email) => {
    // Simple email regex
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const newErrors = {};

    if (!name.trim()) {
      newErrors.name = "Name is required.";
    }
    if (!email.trim()) {
      newErrors.email = "Email is required.";
    } else if (!validateEmail(email)) {
      newErrors.email = "Email format is invalid.";
    }
    if (!message.trim()) {
      newErrors.message = "Message is required.";
    }

    setErrors(newErrors);

    if (Object.keys(newErrors).length === 0) {
      alert("Message sent successfully!");
      setName("");
      setEmail("");
      setMessage("");
    }
  };

  return (
    <main style={{
      maxWidth: 400,
      margin: "2rem auto",
      fontFamily: "'Comic Sans MS', cursive, sans-serif",
      padding: "0 1rem"
    }}>
      <h1 style={{ borderBottom: "2px solid black", paddingBottom: "0.25rem", color: "darkblue" }}>Contact us</h1>
      <p style={{ marginTop: "0.5rem", marginBottom: "1.5rem", lineHeight: 1.4 }}>
        Please fill out the form below to get in touch with us.
      </p>
      <form onSubmit={handleSubmit} noValidate>
        <label htmlFor="name" style={{ display: "block", marginBottom: 4, fontWeight: "bold" }}>
          Name
        </label>
        <input
          id="name"
          type="text"
          value={name}
          onChange={e => setName(e.target.value)}
          style={{
            width: "100%",
            padding: "0.5rem",
            marginBottom: errors.name ? 4 : 16,
            border: "2px solid black",
            borderRadius: 6,
            fontFamily: "'Comic Sans MS', cursive, sans-serif",
            fontSize: "1rem"
          }}
          aria-describedby={errors.name ? "name-error" : undefined}
          aria-invalid={errors.name ? "true" : "false"}
        />
        {errors.name && (
          <p id="name-error" role="alert" style={{ color: "red", marginTop: 0, marginBottom: 12 }}>
            {errors.name}
          </p>
        )}

        <label htmlFor="email" style={{ display: "block", marginBottom: 4, fontWeight: "bold" }}>
          Email
        </label>
        <input
          id="email"
          type="email"
          value={email}
          onChange={e => setEmail(e.target.value)}
          style={{
            width: "100%",
            padding: "0.5rem",
            marginBottom: errors.email ? 4 : 16,
            border: "2px solid black",
            borderRadius: 6,
            fontFamily: "'Comic Sans MS', cursive, sans-serif",
            fontSize: "1rem"
          }}
          aria-describedby={errors.email ? "email-error" : undefined}
          aria-invalid={errors.email ? "true" : "false"}
        />
        {errors.email && (
          <p id="email-error" role="alert" style={{ color: "red", marginTop: 0, marginBottom: 12 }}>
            {errors.email}
          </p>
        )}

        <label htmlFor="message" style={{ display: "block", marginBottom: 4, fontWeight: "bold" }}>
          Message
        </label>
        <textarea
          id="message"
          value={message}
          onChange={e => setMessage(e.target.value)}
          rows={6}
          style={{
            width: "100%",
            padding: "0.5rem",
            marginBottom: errors.message ? 4 : 16,
            border: "2px solid black",
            borderRadius: 6,
            fontFamily: "'Comic Sans MS', cursive, sans-serif",
            fontSize: "1rem",
            resize: "vertical"
          }}
          aria-describedby={errors.message ? "message-error" : undefined}
          aria-invalid={errors.message ? "true" : "false"}
        />
        {errors.message && (
          <p id="message-error" role="alert" style={{ color: "red", marginTop: 0, marginBottom: 12 }}>
            {errors.message}
          </p>
        )}

        <button
          type="submit"
          style={{
            width: "100%",
            padding: "0.75rem",
            borderRadius: 12,
            border: "2px solid black",
            backgroundColor: "white",
            fontFamily: "'Comic Sans MS', cursive, sans-serif",
            fontSize: "1rem",
            cursor: "pointer"
          }}
        >
          Send
        </button>
      </form>
    </main>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

